}

.preview-font-medium {
    font-size: 1rem;
}

.preview-font-large {
    font-size: 1.2rem;
}

.preview-compact {
    padding: 0.75rem;
    line-height: 1.2;
}

.preview-compact .mb-2 {
    margin-bottom: 0.25rem !important;
}

